(() => {
  'use strict';
  const root = document.getElementById('app');
  const storageKey = 'scientara-prototype-v1';
  const journals = {
    aires: {name:'AIRES', full:'Artificial Intelligence and Resilient Engineering Systems', field:'AI & resilient engineering', zh:'人工智能与韧性工程', desc:'Research connecting artificial intelligence with the reliability, safety, adaptability and recovery of engineered systems.', zhdesc:'关注人工智能如何支持工程系统的可靠性、安全性、适应性与恢复能力。', type:'Research & review', klass:'j-aires'},
    industrics: {name:'INDUSTRICS', full:'Industry, Intelligent Systems and Applied Transformation', field:'Industry & intelligent systems', zh:'产业与智能系统', desc:'Research at the intersection of industrial systems, intelligent methods and practical transformation.', zhdesc:'聚焦工业系统、智能方法与实际产业转型之间的交叉研究。', type:'Research & review', klass:'j-industrics'},
    novaxis: {name:'NOVAXIS', full:'Science, Technology and the Emerging Future', field:'Emerging science & technology', zh:'新兴科学与技术', desc:'A multidisciplinary home for emerging science, technology and ideas at the intersections between fields.', zhdesc:'为新兴科学、技术及跨学科前沿研究提供交流空间。', type:'Research & review', klass:'j-novaxis'},
    versionics: {name:'VERSIONICS', full:'A Journal of Usable, Versioned Research Software, Pipelines and Benchmarks', field:'Research software & artifacts', zh:'科研软件与可复现成果', desc:'Research software, pipelines and benchmarks, evaluated through scholarly and artifact review.', zhdesc:'关注科研软件、数据流程和基准工具，结合学术评审与软件成果评审。', type:'Software & artifacts', klass:'j-versionics'}
  };
  const icon = (name,size=17) => {
    const paths={
      arrow:'<path d="M5 12h14M13 6l6 6-6 6"/>',up:'<path d="M7 17 17 7M7 7h10v10"/>',chevron:'<path d="m9 18 6-6-6-6"/>',back:'<path d="M19 12H5m6-6-6 6 6 6"/>',menu:'<path d="M4 7h16M4 12h16M4 17h16"/>',x:'<path d="M18 6 6 18M6 6l12 12"/>',check:'<path d="m5 12 4 4L19 6"/>',book:'<path d="M4 19a3 3 0 0 1 3-3h13M7 3h13v18H7a3 3 0 0 1-3-3V6a3 3 0 0 1 3-3Z"/>',spark:'<path d="m12 3 1.8 5.7L19.5 10.5l-5.7 1.8L12 18l-1.8-5.7-5.7-1.8 5.7-1.8L12 3ZM19 15l.7 2.3L22 18l-2.3.7L19 21l-.7-2.3L16 18l2.3-.7L19 15Z"/>',shield:'<path d="M12 22s8-4 8-11V5l-8-3-8 3v6c0 7 8 11 8 11Z"/><path d="m9 12 2 2 4-4"/>',globe:'<circle cx="12" cy="12" r="9"/><path d="M3 12h18M12 3a14 14 0 0 1 0 18M12 3a14 14 0 0 0 0 18"/>',grid:'<rect x="3" y="3" width="7" height="7" rx="1"/><rect x="14" y="3" width="7" height="7" rx="1"/><rect x="3" y="14" width="7" height="7" rx="1"/><rect x="14" y="14" width="7" height="7" rx="1"/>',file:'<path d="M6 3h8l4 4v14H6z"/><path d="M14 3v5h4M9 13h6M9 17h6"/>',palette:'<circle cx="12" cy="12" r="9"/><path d="M12 21c2-1 2-3 1-4-1-2 1-3 3-3 3 0 4-2 4-4"/><path d="M7 11h.01M9 7h.01M14 7h.01"/>',search:'<circle cx="11" cy="11" r="6"/><path d="m16 16 4 4"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',info:'<circle cx="12" cy="12" r="9"/><path d="M12 11v5M12 8h.01"/>',reset:'<path d="M3 12a9 9 0 1 0 3-6.7L3 8"/><path d="M3 3v5h5"/>',user:'<circle cx="12" cy="8" r="3"/><path d="M5 21a7 7 0 0 1 14 0"/>',upload:'<path d="M12 16V4m-4 4 4-4 4 4M4 17v3h16v-3"/>'
    };
    return `<svg class="icon-${name}" width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${paths[name]||''}</svg>`;
  };
  const basePapers=[
    {id:'DEMO-101',journal:'aires',title:'A resilient monitoring framework for smart infrastructure',author:'Demo Author A',status:'technical',day:'Today',abstract:'A simulated manuscript used to demonstrate the editorial process.',file:'demo-manuscript.pdf'},
    {id:'DEMO-102',journal:'versionics',title:'OpenLab: a reusable research workflow toolkit',author:'Demo Author B',status:'review',day:'Yesterday',abstract:'A simulated software article with an illustrative artifact review.',file:'openlab-demo.zip',scholar:false,artifact:false},
    {id:'DEMO-103',journal:'industrics',title:'Predictive maintenance for connected manufacturing',author:'Demo Author C',status:'revision',day:'2 days ago',abstract:'A simulated article requiring revision.',file:'demo-revision.pdf'},
    {id:'DEMO-104',journal:'novaxis',title:'A framework for interdisciplinary technology research',author:'Demo Author D',status:'review',day:'3 days ago',abstract:'A simulated manuscript under review.',file:'example.pdf'}
  ];
  const initial=()=>({lang:'en',view:'home',journal:'aires',step:0,menu:false,papers:structuredClone(basePapers),selected:'DEMO-101',filter:'all',query:'',workspace:'queue',form:{journal:'aires',type:'Research Paper',title:'',abstract:'',keywords:'',file:'',author:'',email:'',institution:'',consent:false},submitted:false,design:{journal:'aires',accent:'#275a44',tagline:'Research connecting intelligence and resilience.'},designSaved:false,aiChecked:false,modal:null,decision:'revision',error:''});
  let state=initial();
  try{const saved=sessionStorage.getItem(storageKey);if(saved){const x=JSON.parse(saved);state={...state,...x,form:{...state.form,...x.form},design:{...state.design,...x.design},modal:null,error:'',menu:false};}}catch(_){ }
  // The non-final packs are intentionally partial: missing keys fall back to English.
  const LANGUAGES = [
    {code:'en',label:'English',complete:true},
    {code:'zh-CN',label:'简体中文',complete:true},
    {code:'zh-TW',label:'繁體中文',notice:'翻譯尚在進行，部分內容暫以英文顯示。'},
    {code:'es',label:'Español',notice:'Traducción en curso; parte del contenido se muestra en inglés.'},
    {code:'fr',label:'Français',notice:'Traduction en cours : une partie du contenu apparaît en anglais.'},
    {code:'pt',label:'Português',notice:'Tradução em andamento; parte do conteúdo aparece em inglês.'},
    {code:'ar',label:'العربية',dir:'rtl',notice:'الترجمة قيد الإعداد؛ يظهر بعض المحتوى باللغة الإنجليزية.'},
    {code:'ru',label:'Русский',notice:'Перевод готовится; часть текста показана на английском.'},
    {code:'de',label:'Deutsch',notice:'Übersetzung in Arbeit; einige Inhalte erscheinen auf Englisch.'},
    {code:'ja',label:'日本語',notice:'翻訳作業中のため、一部の内容は英語で表示されます。'},
    {code:'ko',label:'한국어',notice:'번역 진행 중이며 일부 내용은 영어로 표시됩니다.'},
    {code:'hi',label:'हिन्दी',notice:'अनुवाद जारी है; कुछ सामग्री अंग्रेज़ी में दिखाई जाएगी।'}
  ];
  const localePacks=Object.create(null);
  const localeMeta=code=>LANGUAGES.find(item=>item.code===code);
  try { const preference=localStorage.getItem('scientara-locale'); if(localeMeta(preference)) state.lang=preference; } catch(_) {}
  if(state.lang==='zh') state.lang='zh-CN';
  if(!localeMeta(state.lang)) state.lang='en';
  const L=(en,zh)=>state.lang==='zh-CN'?zh:state.lang==='en'?en:(localePacks[state.lang]?.[en]||(localeMeta(state.lang)?.dir==='rtl'?'\u2066'+en+'\u2069':en));
  // Locale packs are plain text. Reject markup and attribute-delimiting characters.
  const safePack=pack=>pack && typeof pack==='object' && !Array.isArray(pack) && Object.values(pack).every(value=>typeof value==='string' && value.trim() && !/[<>&"]/u.test(value));
  let languageRequest=0;
  async function changeLanguage(code,restoreFocus=false){
    if(!localeMeta(code)) return;
    const request=++languageRequest;
    if(code!=='en'&&code!=='zh-CN'&&!localePacks[code]){
      try {
        const response=await fetch('./locales/'+code+'.json');
        if(!response.ok) throw new Error('Locale not available');
        const pack=await response.json();
        if(!safePack(pack)) throw new Error('Invalid locale pack');
        localePacks[code]=pack;
      } catch(_) {
        if(request===languageRequest){render();alertToast('Language pack unavailable; please try again.');}
        return;
      }
    }
    if(request!==languageRequest) return;
    state.lang=code;state.error='';
    try { localStorage.setItem('scientara-locale',code); } catch(_) {}
    render();
    if(restoreFocus) document.querySelector('select[name=language]')?.focus();
  }
  const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const save=()=>{try{sessionStorage.setItem(storageKey,JSON.stringify({...state,modal:null,error:'',menu:false}));}catch(_){}};
  const alertToast=(text)=>{const el=document.getElementById('toast');el.textContent=text;el.classList.add('show');clearTimeout(alertToast.timer);alertToast.timer=setTimeout(()=>el.classList.remove('show'),2800)};
  const button=(action,label,cls='btn btn-primary',extra='')=>`<button type="button" class="${cls}" data-action="${action}" ${extra}>${label}</button>`;
  const mark=()=>`<span class="brand-mark">${icon('spark',17)}</span><span>INTELLIGENT<small>PUBLISHING STUDIO</small></span>`;
  const statusLabel=s=>({technical:L('Technical check','技术初审'),review:L('In review','审稿中'),revision:L('Revision requested','待修回'),accepted:L('Accepted','已录用')})[s]||s;
  const badge=s=>`<span class="badge ${s==='revision'?'warm':s==='review'?'blue':''}">${esc(statusLabel(s))}</span>`;
  function header(){
    return `<div class="demo-strip"><div class="container"><span><strong>${L('INTERACTIVE PROTOTYPE','交互原型')}</strong> &nbsp; / &nbsp; ${L('All submissions and activity are simulated','所有稿件与操作均为模拟')}</span><span class="desktop-demo">${L('No live journal data or external services','未连接正式期刊数据或外部服务')}</span><button type="button" data-action="reset">${L('Reset demo','重置演示')}</button></div></div>
    <header class="header"><div class="container header-inner"><button type="button" class="brand" data-action="home" aria-label="Intelligent Publishing Studio home">${mark()}</button>
      <nav class="main-nav ${state.menu?'open':''}" aria-label="${L('Main navigation','主导航')}">
        <button class="nav-link ${state.view==='home'?'active':''}" data-action="home">${L('Home','首页')}</button>
        <button class="nav-link" data-action="browse">${L('Our journals','旗下期刊')}</button>
        <button class="nav-link ${state.view==='submit'?'active':''}" data-action="start">${L('For authors','作者投稿')}</button>
        <button class="nav-link ${state.view==='editor'?'active':''}" data-action="editor">${L('Editor workspace','编辑工作台')}</button>
      </nav><div class="nav-actions"><label class="locale-picker">${icon('globe',15)}<span class="sr-only">${L('Language','语言')}</span><select name="language" aria-label="${L('Language','语言')}">${LANGUAGES.map(item=>`<option value="${item.code}" lang="${item.code}" ${state.lang===item.code?'selected':''}>${item.label}${item.complete?'':' · ◐'}</option>`).join('')}</select></label>${button('start',L('Start submission','开始投稿')+icon('up',14),'btn btn-primary')}<button class="mobile-toggle" data-action="menu" aria-label="${L('Toggle menu','切换菜单')}" aria-expanded="${state.menu}">${icon(state.menu?'x':'menu',21)}</button></div></div></header>${localeMeta(state.lang)?.notice?`<div class="locale-notice" role="status">${localeMeta(state.lang).notice}</div>`:''}`;
  }
  function footer(){return `<footer class="footer"><div class="container footer-grid"><div><button class="brand" data-action="home">${mark()}</button><p>${L('An interactive concept for scholarly publishing.','面向学术出版的交互概念原型。')}</p></div><div class="footer-links"><button data-action="browse">${L('Journals','旗下期刊')}</button><button data-action="start">${L('For authors','作者投稿')}</button><button data-action="editor">${L('Editor workspace','编辑工作台')}</button><button data-action="open-source">${L('Open source','开源')}</button><button data-action="reset">${L('Reset demo','重置演示')}</button></div></div></footer>`}
  function openSource(){return `${header()}<main id="main" class="source-page"><div class="container"><div class="content-card"><div class="eyebrow"><span class="dot"></span>${L('OPEN SOURCE','开源项目')}</div><h1 class="serif">${L('An open platform, built together.','共同建设开放的出版平台。')}</h1><p>${L('This prototype is open source under the Apache License 2.0.','本原型采用 Apache License 2.0 开源许可证。')}</p><p>${L('The community can report issues, improve translations and propose code changes in the public repository.','社区可在公开仓库反馈问题、完善翻译并提出代码修改。')}</p><p>${L('The code license does not automatically grant rights to journal names, logos, manuscript content or other third-party materials.','代码许可证不会自动授予期刊名称、标志、稿件内容或其他第三方材料的使用权。')}</p><p><a class="btn btn-primary" href="https://github.com/ziiyuu-lgtm/intelligent-publishing-studio" target="_blank" rel="noopener noreferrer">${L('View the source repository','查看源码仓库')} ${icon('up',14)}</a></p>${button('home',L('Back to home','返回首页'),'btn btn-light')}</div></div></main>${footer()}`}
  function journalCards(){return Object.entries(journals).map(([id,j])=>`<article class="journal-card"><div class="journal-top ${j.klass}"><strong>${j.name}</strong><small>SCIENTARA &nbsp; / &nbsp; ${L('JOURNAL','期刊')}</small></div><div class="journal-body"><h3>${esc(j.full)}</h3><p>${L(j.field,j.zh)}</p><button class="btn-link" data-action="journal" data-id="${id}">${L('Explore journal','查看期刊')} ${icon('arrow',14)}</button></div></article>`).join('')}
  function home(){return `${header()}<main id="main"><section class="hero"><div class="container hero-grid"><div class="hero-copy"><div class="eyebrow"><span class="dot"></span>${L('A HOME FOR MEANINGFUL RESEARCH','为有价值的研究提供归属')}</div><h1 class="serif">${L('Research deserves a <em>thoughtful home.</em>','让有价值的研究，<em>找到归属。</em>')}</h1><p>${L('A publishing experience built around careful review, clear communication and the people behind every discovery.','以审慎评审、清晰沟通和研究者体验为核心，探索更好的学术出版方式。')}</p><div class="hero-actions">${button('browse',L('Explore our journals','探索旗下期刊')+icon('arrow',15))}${button('start',L('Try the author journey','体验作者投稿'),'btn btn-light')}</div><div class="hero-caption">${L('FOUR JOURNALS. ONE SHARED PURPOSE.','四本期刊，共同探索学术出版。')}</div></div><div class="hero-art" aria-label="${L('Illustration of journal covers','期刊封面插画')}"><div class="art-label">SCIENTARA &nbsp; / &nbsp; 01—04</div><div class="cover cover-a"><span class="cover-kicker">SCIENTARA &nbsp; / &nbsp; JOURNAL</span><span class="cover-name">AIRES</span><span class="cover-sub">Artificial Intelligence and Resilient Engineering Systems</span><span class="cover-graphic"></span></div><div class="cover cover-b"><span class="cover-kicker">SCIENTARA &nbsp; / &nbsp; JOURNAL</span><span class="cover-name">VERSIONICS</span><span class="cover-sub">Usable, versioned research software and artifacts</span><span class="cover-graphic"></span></div><div class="art-footer">INQUIRY &nbsp; / &nbsp; DISCOVERY &nbsp; / &nbsp; IMPACT</div></div></div></section>
    <div class="feature-row"><div class="container feature-grid"><div class="feature"><div class="feature-icon">${icon('book',17)}</div><div><strong>${L('Distinct journal identities','独立期刊特色')}</strong><span>${L('A home for each community','服务不同学术社群')}</span></div></div><div class="feature"><div class="feature-icon">${icon('shield',17)}</div><div><strong>${L('Human-led review','以人为主导的评审')}</strong><span>${L('Thoughtful editorial oversight','注重编辑判断与责任')}</span></div></div><div class="feature"><div class="feature-icon">${icon('globe',17)}</div><div><strong>${L('Open research','开放研究')}</strong><span>${L('Ideas made more discoverable','让研究更易被发现')}</span></div></div></div></div>
    <section class="section" id="journals"><div class="container"><div class="section-header"><div><div class="eyebrow"><span class="dot"></span>${L('THE SCIENTARA COLLECTION','SCIENTARA 期刊群')}</div><h2 class="serif">${L('Find the right journal.','找到适合您的期刊。')}</h2></div><p>${L('Four distinct perspectives, connected by a commitment to meaningful and responsible research.','四本各具特色的期刊，共同关注有价值、负责任的研究。')}</p></div><div class="journal-grid">${journalCards()}</div><div class="section-footer"><span>${L('Choose a journal to explore its proposed experience.','选择一本期刊，体验建议中的期刊页面。')}</span><button class="btn-link" data-action="start">${L('Begin a demo submission','开始模拟投稿')} ${icon('arrow',14)}</button></div></div></section>
    <section class="workflow-section"><div class="container workflow-grid"><div class="workflow-copy"><div class="eyebrow"><span class="dot"></span>${L('A MORE THOUGHTFUL PROCESS','更清晰的出版体验')}</div><h2 class="serif">${L('From first idea to<br><em>shared knowledge.</em>','从最初的想法到<br><em>可共享的知识。</em>')}</h2><p>${L('A connected journey for authors and editors, designed to make each stage understandable and every next step clear.','连接作者与编辑的工作流程，让每个环节更清晰，让下一步更明确。')}</p>${button('editor',L('Explore the editor workspace','体验编辑工作台')+icon('arrow',14),'btn btn-dark')}</div><div class="workflow-steps"><div class="workflow-step"><div class="step-number">01</div><div><h3>${L('Find your journal','选择期刊')}</h3><p>${L('Explore scope and choose the right home for your work.','了解各刊定位，为研究选择合适的期刊。')}</p></div></div><div class="workflow-step"><div class="step-number">02</div><div><h3>${L('Prepare your submission','准备投稿')}</h3><p>${L('A guided path keeps the essentials in one place.','通过引导式流程填写稿件与作者信息。')}</p></div></div><div class="workflow-step"><div class="step-number">03</div><div><h3>${L('Review with care','审慎评审')}</h3><p>${L('Editors retain responsibility for review and decisions.','编辑与审稿人负责评审及相关决定。')}</p></div></div></div></div></section></main>${footer()}`}
  function journal(){const j=journals[state.journal]||journals.aires;return `${header()}<main id="main"><div class="subnav"><div class="container subnav-inner"><button class="btn-link" data-action="browse">${icon('back',14)} ${L('All journals','全部期刊')}</button><span class="crumb">/ &nbsp; <strong>${j.name}</strong></span><span class="subnav-spacer"></span><button class="language" data-action="start" data-id="${state.journal}">${L('SUBMIT TO THIS JOURNAL','向本刊投稿')} ${icon('up',12)}</button></div></div><section class="journal-hero"><div class="container journal-hero-grid"><div><div class="eyebrow"><span class="dot"></span>SCIENTARA &nbsp; / &nbsp; ${L('JOURNAL EXPERIENCE','期刊展示')}</div><h1 class="serif">${j.name}</h1><div class="journal-full serif">${esc(j.full)}</div><p class="journal-description">${L(j.desc,j.zhdesc)}</p><div class="journal-hero-actions">${button('start',L('Start a demo submission','开始模拟投稿')+icon('arrow',15),'btn btn-primary',`data-id="${state.journal}"`)}${button('editor',L('Explore editorial view','查看编辑工作台'),'btn btn-light')}</div></div><div class="journal-cover-large ${j.klass}"><small>SCIENTARA / JOURNAL</small><strong>${j.name}</strong><p>${esc(j.full)}</p></div></div></section><div class="container journal-content"><div class="content-card"><div class="eyebrow"><span class="dot"></span>${L('ABOUT THIS JOURNAL','关于本刊')}</div><h2 class="serif">${L('A distinct home for your work.','为研究提供专属空间。')}</h2><p>${L(j.desc,j.zhdesc)}</p>${state.journal==='versionics'?`<div class="track-grid"><div class="track"><strong>${L('01 / Scholarly review','01 / 学术评审')}</strong><p>${L('Evaluate the research contribution and evidence.','评估研究贡献与证据。')}</p></div><div class="track"><strong>${L('02 / Artifact review','02 / 软件成果评审')}</strong><p>${L('Consider the exact software version and its usability.','评估具体软件版本及其可用性。')}</p></div></div>`:`<div class="track-grid"><div class="track"><strong>${L('Thoughtful peer review','审慎的同行评审')}</strong><p>${L('A clear workflow for authors and editors.','为作者与编辑提供清晰流程。')}</p></div><div class="track"><strong>${L('Clear communication','清晰的交流')}</strong><p>${L('Keep each stage visible and understandable.','使每个阶段清晰可见。')}</p></div></div>`}</div><aside class="journal-aside"><div class="content-card"><div class="aside-heading">${L('At a glance','期刊概览')}</div><div class="aside-row"><span class="muted">${L('Journal','期刊')}</span><strong>${j.name}</strong></div><div class="aside-row"><span class="muted">${L('Focus','方向')}</span><span>${L(j.field,j.zh)}</span></div><div class="aside-row"><span class="muted">${L('Experience','页面状态')}</span><span>${L('Prototype','交互原型')}</span></div></div><div class="note">${icon('info',15)} &nbsp; ${L('This is a design prototype. Journal details and policies should be confirmed on the official site.','这是设计原型。具体期刊信息与政策请以正式网站为准。')}</div></aside></div></main>${footer()}`}
  const steps=()=>[L('Journal & type','期刊与类型'),L('Manuscript','稿件信息'),L('Author details','作者信息'),L('Review & submit','检查并提交')];
  function submissionBody(){const f=state.form;
    if(state.submitted)return `<div class="form-body"><div class="success-block"><div class="success-icon">${icon('check',26)}</div><h2>${L('Demo submission complete.','模拟投稿已完成。')}</h2><p>${L('Your example is now visible in the simulated editor workspace. No manuscript was sent and no email was generated.','示例稿件已显示在模拟编辑工作台中。没有发送稿件或邮件。')}</p><div class="note">${L('Reference','模拟编号')}: <strong>DEMO-NEW</strong> · ${L('Technical check','技术初审')}</div><div class="hero-actions">${button('editor',L('Open editor workspace','打开编辑工作台')+icon('arrow',14))}${button('new-submission',L('Start another demo','再次体验'),'btn btn-light')}</div></div></div>`;
    if(state.step===0)return `<div class="form-body">${state.error?`<div class="error" role="alert">${esc(state.error)}</div>`:''}<div class="form-row"><span class="field-label">${L('Choose a journal','选择期刊')} <span class="required">*</span></span><div class="radio-grid">${Object.entries(journals).map(([id,j])=>`<label class="radio-card ${f.journal===id?'selected':''}"><input type="radio" name="journal" value="${id}" ${f.journal===id?'checked':''}><span><strong>${j.name}</strong><span>${L(j.field,j.zh)}</span></span></label>`).join('')}</div></div><div class="form-row"><label for="type">${L('Article type','文章类型')} <span class="required">*</span></label><select id="type" name="type" class="select"><option value="Research Paper" ${f.type==='Research Paper'?'selected':''}>${L('Research Paper','研究论文')}</option><option value="Review Paper" ${f.type==='Review Paper'?'selected':''}>${L('Review Paper','综述论文')}</option><option value="Software Tool Article" ${f.type==='Software Tool Article'?'selected':''}>${L('Software Tool Article','软件工具论文')}</option></select><div class="help">${L('Options are illustrative and should be configured for each journal.','文章类型为演示选项，可按期刊实际要求配置。')}</div></div></div>`;
    if(state.step===1)return `<div class="form-body">${state.error?`<div class="error" role="alert">${esc(state.error)}</div>`:''}<div class="form-row"><label for="title">${L('Manuscript title','稿件题目')} <span class="required">*</span></label><input class="input" id="title" name="title" value="${esc(f.title)}" placeholder="${L('Enter a sample title','输入模拟稿件题目')}"></div><div class="form-row"><label for="abstract">${L('Abstract','摘要')} <span class="required">*</span></label><textarea class="textarea" id="abstract" name="abstract" placeholder="${L('Add a short sample abstract','输入模拟摘要')}">${esc(f.abstract)}</textarea></div><div class="form-row"><label for="keywords">${L('Keywords','关键词')}</label><input class="input" id="keywords" name="keywords" value="${esc(f.keywords)}" placeholder="${L('e.g. reliability, intelligent systems','例如：韧性、智能系统')}"></div><div class="form-row"><span class="field-label">${L('Manuscript file','稿件文件')}</span><div class="upload">${icon('upload',20)}<div>${L('Optional: select a test file name for this demo','可选：选择测试文件以演示文件名')}</div><input type="file" id="file" name="file" aria-label="${L('Select a test file','选择测试文件')}"><div class="help">${f.file?`${L('Selected','已选择')}: ${esc(f.file)}`:L('Only the file name is read; no file is uploaded.','仅读取文件名，不上传或读取文件内容。')}</div></div></div></div>`;
    if(state.step===2)return `<div class="form-body">${state.error?`<div class="error" role="alert">${esc(state.error)}</div>`:''}<div class="note">${L('Please enter fictional details only. This prototype stores the information in this browser session.','请仅输入虚构信息。本原型仅在当前浏览器会话中保存演示内容。')}</div><div style="height:20px"></div><div class="two-col"><div class="form-row"><label for="author">${L('Corresponding author','通讯作者')} <span class="required">*</span></label><input class="input" id="author" name="author" value="${esc(f.author)}" placeholder="Demo Author"></div><div class="form-row"><label for="email">${L('Email address','电子邮箱')} <span class="required">*</span></label><input class="input" id="email" name="email" type="email" value="${esc(f.email)}" placeholder="author@example.org"></div></div><div class="form-row"><label for="institution">${L('Affiliation','所属机构')}</label><input class="input" id="institution" name="institution" value="${esc(f.institution)}" placeholder="Example University"></div></div>`;
    return `<div class="form-body">${state.error?`<div class="error" role="alert">${esc(state.error)}</div>`:''}<div class="review-list"><div class="review-entry"><span>${L('Journal','期刊')}</span><strong>${journals[f.journal].name}</strong></div><div class="review-entry"><span>${L('Article type','文章类型')}</span><strong>${esc(({ 'Research Paper':L('Research Paper','研究论文'), 'Review Paper':L('Review Paper','综述论文'), 'Software Tool Article':L('Software Tool Article','软件工具论文') })[f.type]||f.type)}</strong></div><div class="review-entry"><span>${L('Title','题目')}</span><strong>${esc(f.title)}</strong></div><div class="review-entry"><span>${L('Abstract','摘要')}</span><div>${esc(f.abstract)}</div></div><div class="review-entry"><span>${L('Corresponding author','通讯作者')}</span><strong>${esc(f.author)} · ${esc(f.email)}</strong></div><div class="review-entry"><span>${L('File','文件')}</span><div>${esc(f.file||L('No file selected','未选择文件'))}</div></div></div><label class="checkline"><input type="checkbox" name="consent" ${f.consent?'checked':''}><span>${L('I understand this is a simulated submission and no real manuscript will be sent.','我了解这是模拟投稿，不会发送真实稿件。')}</span></label><div class="note">${L('Any AI suggestions in this prototype are illustrative; no external AI model is connected.','本原型中的 AI 建议仅为演示，尚未连接外部模型。')}</div></div>`;
  }
  function submit(){const s=steps();const j=journals[state.form.journal];return `${header()}<main id="main" class="portal-shell"><div class="container"><div class="portal-breadcrumb">SCIENTARA &nbsp; / &nbsp; ${L('Author centre','作者中心')} &nbsp; / &nbsp; ${L('New submission','新建投稿')}</div><div class="portal-title"><div><div class="eyebrow"><span class="dot"></span>${L('AUTHOR CENTRE','作者中心')}</div><h1 class="serif">${state.submitted?L('Your submission','您的投稿'):L('Start a submission','开始投稿')}</h1><p>${L('A guided submission experience using sample information.','使用模拟信息，体验引导式投稿流程。')}</p></div>${button('fill',L('Use example data','填入示例数据'),'btn btn-light')}</div><div class="portal-grid"><aside class="step-list"><h2>${L('SUBMISSION STEPS','投稿步骤')}</h2>${s.map((x,i)=>`<div class="step-item ${i===state.step&&!state.submitted?'active':''} ${i<state.step||state.submitted?'done':''}"><span class="step-circle">${i<state.step||state.submitted?icon('check',13):i+1}</span><span class="step-name">${x}</span></div>`).join('')}<div class="privacy">${icon('shield',14)} &nbsp; ${L('Demo data stays in this browser session.','演示数据保存在本次浏览器会话中。')}</div></aside><section class="form-card" aria-label="${L('Submission form','投稿表单')}">${!state.submitted?`<div class="form-head"><div class="caps">${L('STEP','第')} ${state.step+1} / 4 &nbsp; · &nbsp; ${j.name}</div><h2>${[L('Find the right home','选择适合的期刊'),L('Tell us about your work','填写稿件信息'),L('Who is submitting?','填写作者信息'),L('One final review','最后检查')][state.step]}</h2><p>${[L('Choose a journal and article type to begin.','选择期刊和文章类型。'),L('Add the essential information about your example.','填写演示稿件的基本信息。'),L('Add a fictional corresponding author.','填写一位虚构的通讯作者。'),L('Check the details before completing the simulation.','确认信息后完成模拟投稿。')][state.step]}</p></div>`:''}${submissionBody()}${!state.submitted?`<div class="form-footer"><div class="left">${state.step>0?button('prev',icon('back',14)+' '+L('Back','上一步'),'btn btn-light'):button('home',L('Cancel','返回首页'),'btn btn-light')}</div><div class="right"><button class="btn-link" data-action="fill">${L('Use example','填入示例')}</button>${state.step<3?button('next',L('Continue','继续')+' '+icon('arrow',14)):button('finish',L('Complete demo','完成模拟')+' '+icon('arrow',14))}</div></div>`:''}</section></div></div></main>`}
  const selectedPaper=()=>state.papers.find(p=>p.id===state.selected)||state.papers[0];
  function sideLink(target,label,ico){return `<button class="side-link ${state.workspace===target?'selected':''}" data-action="workspace" data-tab="${target}">${icon(ico,15)} ${label}</button>`}
  function editorSidebar(){return `<aside class="workspace-side"><div class="side-logo">INTELLIGENT &nbsp; / &nbsp; STUDIO</div><div class="side-section">${L('WORKSPACE','工作空间')}</div>${sideLink('queue',L('Editorial overview','编辑概览'),'grid')}${sideLink('submissions',L('Submissions','稿件列表'),'file')}<div class="side-section">${L('JOURNAL TOOLS','期刊工具')}</div>${sideLink('design',L('Journal appearance','期刊外观'),'palette')}${sideLink('ai',L('AI-assisted checks','AI 辅助检查'),'spark')}<div class="side-bottom">${icon('shield',14)}<br>${L('This workspace contains simulated records only.','本工作台仅包含模拟记录。')}</div></aside>`}
  function metrics(){const papers=state.papers;return `<div class="metric-grid"><div class="metric"><div class="metric-label">${L('Demo submissions','模拟稿件')}</div><div class="metric-num">${papers.length}</div><div class="metric-sub">${L('Sample records','示例记录')}</div></div><div class="metric"><div class="metric-label">${L('Technical check','技术初审')}</div><div class="metric-num">${papers.filter(p=>p.status==='technical').length}</div><div class="metric-sub">${L('Awaiting editor review','等待编辑处理')}</div></div><div class="metric"><div class="metric-label">${L('In peer review','同行评审中')}</div><div class="metric-num">${papers.filter(p=>p.status==='review').length}</div><div class="metric-sub">${L('Across sample journals','跨示例期刊')}</div></div><div class="metric"><div class="metric-label">${L('Revision requested','待修回')}</div><div class="metric-num">${papers.filter(p=>p.status==='revision').length}</div><div class="metric-sub">${L('Waiting for author','等待作者修回')}</div></div></div>`}
  function paperList(){const filtered=state.papers.filter(p=>(state.filter==='all'||p.status===state.filter)&&(`${p.id} ${p.title} ${journals[p.journal].name}`.toLowerCase().includes(state.query.toLowerCase())));return `<div class="panel"><div class="panel-head"><div><h2>${L('Submission queue','稿件队列')}</h2><p>${L('Select a sample to view the workflow.','选择一条模拟稿件查看流程。')}</p></div><select class="filter" name="filter" aria-label="${L('Filter submissions','筛选稿件')}"><option value="all" ${state.filter==='all'?'selected':''}>${L('All statuses','全部状态')}</option><option value="technical" ${state.filter==='technical'?'selected':''}>${L('Technical check','技术初审')}</option><option value="review" ${state.filter==='review'?'selected':''}>${L('In review','审稿中')}</option><option value="revision" ${state.filter==='revision'?'selected':''}>${L('Revision','待修回')}</option><option value="accepted" ${state.filter==='accepted'?'selected':''}>${L('Accepted','已录用')}</option></select></div><div class="search-row"><input class="input" id="paper-search" name="query" value="${esc(state.query)}" placeholder="${L('Search sample titles or journals…','搜索模拟稿件或期刊…')}" aria-label="${L('Search submissions','搜索稿件')}"></div>${filtered.length?filtered.map(p=>`<button class="paper-row ${p.id===state.selected?'selected':''}" data-action="select-paper" data-id="${esc(p.id)}"><span class="paper-initial">${journals[p.journal].name.slice(0,1)}</span><span class="paper-body"><span class="paper-title">${esc(p.title)}</span><span class="paper-meta">${p.id} &nbsp; · &nbsp; ${journals[p.journal].name} &nbsp; · &nbsp; ${esc(p.author)}</span></span>${badge(p.status)}</button>`).join(''):`<div class="empty">${L('No matching sample records.','没有匹配的模拟记录。')}</div>`}</div>`}
  function details(){const p=selectedPaper();if(!p)return '';return `<div><div class="panel"><div class="panel-head"><div><h2>${L('Manuscript details','稿件详情')}</h2><p>${esc(p.id)} &nbsp; · &nbsp; ${L('Simulated record','模拟记录')}</p></div>${badge(p.status)}</div><div class="detail"><div class="detail-label">${journals[p.journal].name}</div><h3>${esc(p.title)}</h3><div class="detail-row"><span>${L('Author','作者')}</span><strong>${esc(p.author)}</strong></div><div class="detail-row"><span>${L('File','文件')}</span><strong>${esc(p.file||L('Not provided','未提供'))}</strong></div><div class="detail-row"><span>${L('Activity','更新时间')}</span><strong>${esc(p.day)}</strong></div>${p.journal==='versionics'?`<div class="track-state"><strong>${L('Dual-track review','双轨评审')}</strong><div>${L('Scholarly review','学术评审')}: ${p.scholar?L('Complete','已完成'):L('Pending','待完成')} · <button class="btn-link" data-action="toggle-track" data-track="scholar">${L('Toggle','切换')}</button></div><div>${L('Artifact review','软件成果评审')}: ${p.artifact?L('Complete','已完成'):L('Pending','待完成')} · <button class="btn-link" data-action="toggle-track" data-track="artifact">${L('Toggle','切换')}</button></div></div>`:''}${button('move-review',L('Move to review','进入审稿')+icon('arrow',14),'btn btn-primary',p.status==='accepted'?'disabled':'')}${button('decision-open',L('Record a demo decision','记录模拟决定'),'btn btn-light',p.status==='accepted'?'disabled':'')}</div></div><div class="ai-panel"><div class="eyebrow">${icon('spark',14)} &nbsp; ${L('EDITOR ASSIST','编辑辅助')}</div><h3>${L('A little help, with you in control.','辅助信息，由您掌控。')}</h3><p>${L('Preview an illustrative check. Editorial decisions always remain with people.','查看模拟检查。编辑决定始终由人工作出。')}</p><button class="btn-link" data-action="workspace" data-tab="ai">${L('Open demo assistant','打开模拟助手')} ${icon('arrow',13)}</button></div></div>`}
  function queue(){return `${metrics()}<div class="dashboard-grid">${paperList()}${details()}</div>`}
  function design(){let d=state.design;return `<div class="design-layout"><div class="panel design-form"><div class="eyebrow"><span class="dot"></span>${L('JOURNAL DESIGNER','期刊设计')}</div><h2 class="serif" style="font-size:28px;margin:10px 0">${L('Make it yours.','设计期刊风格。')}</h2><p class="muted tiny">${L('Try a journal identity and see the preview update. Changes stay in this demo.','选择期刊和配色，即时预览；更改仅用于本次演示。')}</p><div class="form-row"><label for="design-journal">${L('Journal','期刊')}</label><select class="select" name="designJournal" id="design-journal">${Object.entries(journals).map(([id,j])=>`<option value="${id}" ${d.journal===id?'selected':''}>${j.name}</option>`).join('')}</select></div><div class="form-row"><span class="field-label">${L('Accent colour','主题颜色')}</span><div class="swatch-grid">${['#275a44','#344d68','#80674e','#654e62'].map(color=>`<button class="swatch ${d.accent===color?'selected':''}" style="background:${color}" data-action="accent" data-color="${color}" aria-label="${L('Choose colour','选择颜色')} ${color}" aria-pressed="${d.accent===color}"></button>`).join('')}</div></div><div class="form-row"><label for="tagline">${L('Journal tagline','期刊介绍语')}</label><input class="input" name="tagline" id="tagline" value="${esc(d.tagline)}" maxlength="110"><div class="help">${L('Use sample text only.','请仅使用示例文字。')}</div></div>${button('save-design',L('Save demo preview','保存演示预览'),'btn btn-primary')}${d.designSaved?'<span></span>':''}</div><div class="mock-page" style="--accent:${esc(d.accent)}"><div class="mock-bar"><i></i><i></i><i></i></div><div class="mock-nav">SCIENTARA &nbsp; / &nbsp; ${journals[d.journal].name}</div><div class="mock-hero"><small>${L('JOURNAL PAGE PREVIEW','期刊页面预览')}</small><h2>${journals[d.journal].name}</h2><p id="live-tagline">${esc(d.tagline)}</p><span class="btn btn-white" style="margin-top:10px">${L('Explore the journal','探索期刊')}</span></div><div class="mock-lines"><b>${L('Aims & scope','期刊定位')}</b><i></i><i></i><i></i></div></div></div>`}
  function ai(){const p=selectedPaper();return `<div class="dashboard-grid"><div class="panel"><div class="panel-head"><div><h2>${L('Illustrative manuscript check','模拟稿件检查')}</h2><p>${L('A preview of how a reviewer-facing assistant could present information.','展示编辑辅助工具可如何呈现检查信息。')}</p></div>${icon('spark',19)}</div><div class="detail"><div class="note">${L('Simulation only: no AI model, reference database or manuscript service is connected.','仅供演示：未连接 AI 模型、文献数据库或稿件服务。')}</div><div style="height:12px"></div><div class="detail-row"><span>${L('Selected manuscript','所选稿件')}</span><strong>${esc(p?.id||'—')}</strong></div><div class="detail-row"><span>${L('Journal','期刊')}</span><strong>${p?journals[p.journal].name:'—'}</strong></div>${button('run-check',L('Run illustrative check','运行模拟检查')+icon('spark',14),'btn btn-primary')}${state.aiChecked?`<div class="track-state" role="status"><strong>${L('Example output','示例输出')}</strong><div>✓ ${L('Title and journal are present.','已填写题目与期刊。')}</div><div>• ${L('Reference verification requires an authorised source.','文献核验需要接入获授权的数据源。')}</div><div>• ${L('An editor should review all findings.','所有提示均需由编辑复核。')}</div></div>`:''}</div></div><div class="panel"><div class="panel-head"><div><h2>${L('Human oversight','人工审核')}</h2><p>${L('Suggested operating principle','建议的工作原则')}</p></div>${icon('shield',18)}</div><div class="detail"><p class="muted tiny">${L('Assistance can organise and flag information. An authorised editor reviews the evidence and makes each editorial decision.','辅助工具可以整理和提示信息。授权编辑应核对证据并作出编辑决定。')}</p>${button('workspace',L('Return to queue','返回稿件队列'),'btn btn-light','data-tab="queue"')}</div></div></div>`}
  function modal(){if(!state.modal)return '';if(state.modal==='decision'){const p=selectedPaper();return `<div class="modal-backdrop"><div class="modal" role="dialog" aria-modal="true" aria-labelledby="modal-title"><h2 id="modal-title">${L('Record a demo decision','记录模拟决定')}</h2><p>${L('This changes only the example record in this browser session. No message will be sent.','仅更改当前浏览器会话中的示例记录，不会发送任何消息。')}</p><div class="form-row"><label for="decision">${L('Decision','决定')}</label><select class="select" id="decision" name="decision"><option value="revision" ${state.decision==='revision'?'selected':''}>${L('Request revision','要求修回')}</option><option value="accepted" ${state.decision==='accepted'?'selected':''}>${L('Accept (demo)','录用（演示）')}</option></select></div>${p?.journal==='versionics'?`<div class="note">${L('For this example, both scholarly and artifact tracks must be complete before an acceptance can be simulated.','本示例中，模拟录用前须先完成学术与软件成果两个评审环节。')}</div>`:''}<div class="modal-actions">${button('close-modal',L('Cancel','取消'),'btn btn-light')}${button('confirm-decision',L('Confirm demo decision','确认模拟决定'),'btn btn-primary')}</div></div></div>`}return ''}
  function editor(){let titles={queue:L('Editorial overview','编辑概览'),submissions:L('Submissions','稿件列表'),design:L('Journal appearance','期刊外观'),ai:L('AI-assisted checks','AI 辅助检查')};return `${header()}<main id="main" class="workspace">${editorSidebar()}<div class="workspace-main"><div class="workspace-top"><div><div class="eyebrow"><span class="dot"></span>${L('EDITOR WORKSPACE','编辑工作台')}</div><h1>${titles[state.workspace]||titles.queue}</h1><p>${L('Explore a connected editorial experience using simulated records.','使用模拟记录体验相互衔接的编辑流程。')}</p></div><div class="workspace-profile"><div class="avatar">ED</div><span>${L('Demo editor','模拟编辑')}<br><span class="muted">SCIENTARA</span></span></div></div>${state.workspace==='design'?design():state.workspace==='ai'?ai():queue()}</div></main>${modal()}`}
  function render(){document.documentElement.lang=state.lang;document.documentElement.dir=localeMeta(state.lang)?.dir||'ltr';document.querySelector('.skip-link').textContent=L('Skip to content','跳到主要内容');root.innerHTML=state.view==='home'?home():state.view==='journal'?journal():state.view==='submit'?submit():state.view==='source'?openSource():editor();const pageTitle=state.view==='editor'?'Editorial Studio':state.view==='submit'?'Submit a Manuscript':state.view==='journal'?journals[state.journal].name:state.view==='source'?'Open Source':'';document.title=pageTitle?pageTitle+' | Intelligent Publishing Studio':'Intelligent Publishing Studio';save();}
  function goto(view){state.view=view;state.menu=false;state.error='';state.modal=null;render();window.scrollTo({top:0,behavior:'instant'});}
  function validate(){const f=state.form;if(state.step===1){if(f.title.trim().length<4||f.abstract.trim().length<10){state.error=L('Please add a sample title and a short abstract.','请填写模拟题目和摘要。');return false;}}if(state.step===2){if(!f.author.trim()||!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(f.email.trim())){state.error=L('Please add a fictional author and a valid example email.','请填写虚构作者和格式正确的示例邮箱。');return false;}}if(state.step===3&&!f.consent){state.error=L('Please confirm you understand this is a simulation.','请确认您了解这是模拟投稿。');return false;}state.error='';return true;}
  function fill(){state.form={journal:state.form.journal,type:state.form.journal==='versionics'?'Software Tool Article':'Research Paper',title:'A sample framework for resilient research systems',abstract:'This simulated manuscript demonstrates a guided publishing and peer-review workflow for research teams.',keywords:'simulation, resilience, publishing',file:'example-manuscript.pdf',author:'Demo Author',email:'author@example.org',institution:'Example University',consent:false};state.error='';render();alertToast(L('Example data added.','已填入示例数据。'));}
  root.addEventListener('click',ev=>{const el=ev.target.closest('[data-action]');if(!el||el.disabled)return;const a=el.dataset.action;
    if(a==='home')goto('home');
    else if(a==='browse'){state.view='home';state.menu=false;render();requestAnimationFrame(()=>document.getElementById('journals')?.scrollIntoView({behavior:'smooth'}));}
    else if(a==='journal'){state.journal=el.dataset.id;goto('journal');}
    else if(a==='start'){if(el.dataset.id)state.form.journal=el.dataset.id;else if(state.view==='journal')state.form.journal=state.journal;state.submitted=false;state.step=0;goto('submit');}
    else if(a==='editor'){state.workspace='queue';goto('editor');}
    else if(a==='open-source')goto('source');
    else if(a==='menu'){state.menu=!state.menu;render();}
    else if(a==='reset'){if(window.confirm(L('Reset all demo activity in this browser session?','重置本次会话中的所有演示数据？'))){const lang=state.lang;state=initial();state.lang=lang;render();window.scrollTo(0,0);alertToast(L('Demo reset.','演示已重置。'));}}
    else if(a==='fill')fill();
    else if(a==='next'){if(validate())state.step=Math.min(3,state.step+1);render();window.scrollTo({top:0,behavior:'smooth'});}
    else if(a==='prev'){state.step=Math.max(0,state.step-1);state.error='';render();window.scrollTo({top:0,behavior:'smooth'});}
    else if(a==='finish'){if(validate()){const f=state.form;state.papers=state.papers.filter(p=>p.id!=='DEMO-NEW');state.papers.unshift({id:'DEMO-NEW',journal:f.journal,title:f.title,author:f.author,status:'technical',day:L('Just now','刚刚'),abstract:f.abstract,file:f.file,scholar:false,artifact:false});state.selected='DEMO-NEW';state.submitted=true;}render();window.scrollTo({top:0,behavior:'smooth'});}
    else if(a==='new-submission'){state.form=initial().form;state.step=0;state.submitted=false;render();}
    else if(a==='workspace'){state.workspace=el.dataset.tab||'queue';state.aiChecked=false;render();}
    else if(a==='select-paper'){state.selected=el.dataset.id;state.aiChecked=false;render();}
    else if(a==='move-review'){const p=selectedPaper();if(p&&p.status!=='accepted'){p.status='review';p.day=L('Just now','刚刚');render();alertToast(L('Sample moved to review. No invitation was sent.','示例稿件已进入审稿，未发送邀请。'));}}
    else if(a==='toggle-track'){const p=selectedPaper();if(p&&p.journal==='versionics'&&['scholar','artifact'].includes(el.dataset.track)){p[el.dataset.track]=!p[el.dataset.track];render();}}
    else if(a==='decision-open'){state.decision='revision';state.modal='decision';render();document.querySelector('#decision')?.focus();}
    else if(a==='close-modal'){state.modal=null;render();}
    else if(a==='confirm-decision'){const p=selectedPaper();if(p?.journal==='versionics'&&state.decision==='accepted'&&(!p.scholar||!p.artifact)){alertToast(L('Complete both demo review tracks first.','请先完成两项模拟评审。'));return;}if(p){p.status=state.decision;p.day=L('Just now','刚刚');}state.modal=null;render();alertToast(L('Demo decision recorded. No email was sent.','已记录模拟决定，未发送邮件。'));}
    else if(a==='accent'){state.design.accent=el.dataset.color;state.designSaved=false;render();}
    else if(a==='save-design'){state.designSaved=true;save();alertToast(L('Preview saved for this browser session.','演示预览已保存至当前浏览器会话。'));}
    else if(a==='run-check'){state.aiChecked=true;render();}
  });
  root.addEventListener('input',ev=>{const e=ev.target,n=e.name;if(['title','abstract','keywords','author','email','institution'].includes(n)){state.form[n]=e.value;save();}else if(n==='tagline'){state.design.tagline=e.value;state.designSaved=false;const live=document.getElementById('live-tagline');if(live)live.textContent=e.value;save();}else if(n==='query'){state.query=e.value;const start=e.selectionStart;render();const input=document.getElementById('paper-search');if(input){input.focus();input.setSelectionRange(start,start);}}});
  root.addEventListener('change',ev=>{const e=ev.target,n=e.name;if(n==='language'){void changeLanguage(e.value,true);return;}else if(n==='journal'){state.form.journal=e.value;render();}else if(n==='type'){state.form.type=e.value;save();}else if(n==='consent'){state.form.consent=e.checked;save();}else if(n==='file'){state.form.file=e.files?.[0]?.name||'';render();}else if(n==='filter'){state.filter=e.value;render();}else if(n==='decision'){state.decision=e.value;save();}else if(n==='designJournal'){state.design.journal=e.value;state.design.tagline=state.lang==='zh-CN'?journals[e.value].zhdesc:journals[e.value].desc;state.designSaved=false;render();}});
  document.addEventListener('keydown',ev=>{if(ev.key==='Escape'&&state.modal){state.modal=null;render();}});
  render();
  if(state.lang!=='en'&&state.lang!=='zh-CN') void changeLanguage(state.lang);
})();
